    agregar("G34-L3-13", CLASE_34, "L3", "Inspección de volante bimasa (DMF) acoplado a embrague desgastado: juego angular libre de 28 grados (límite de servicio 14 grados) y juego axial de 2.2 mm con fuga de grasa de silicona por choque térmico continuo derivado del patinamiento crónico del disco de embrague.", "TECNICO", "metrologia_volante_bimasa_28_grados", "bimasa_juego_28_grados_vs_14|juego_axial_2_2mm|grasa_fugada_calor", "falla_caja_cambios", "", "NO", "SI", "Rodajes de transmision manual o eje primario gastados", "L3 juego bimasa excesivo de 28° derivado de sobrecalentamiento crónico.")
