    # --- L1 (10 casos) ---
    agregar("G37-L1-01", CLASE_37, "L1", "La transmisión zumba como una turbina cada vez que acelero en pista.", "COTIDIANO", "aceleracion_pista", "zumbido_turbina_al_acelerar", "", "", "SI", "NO", "", "L1 zumbido de transmisión bajo carga.")
    agregar("G37-L1-02", CLASE_37, "L1", "Hola, siento un aullido sordo debajo del centro del carro que cambia al soltar el gas.", "WHATSAPP", "retencion", "aullido_centro_cambia_al_soltar_gas", "", "", "SI", "NO", "", "L1 aullido de piñón y corona de diferencial.")
    agregar("G37-L1-03", CLASE_37, "L1", "Se escucha un ronroneo metálico constante que aumenta con la velocidad del carro.", "COTIDIANO", "rodadura_velocidad", "ronroneo_aumenta_con_velocidad", "", "", "SI", "NO", "", "L1 zumbido proporcional a velocidad vehicular.")
    agregar("G37-L1-04", CLASE_37, "L1", "Al desacelerar en quinta suena un quejido áspero en la parte de abajo de la caja.", "TALLER", "desaceleracion_quinta", "quejido_aspero_desaceleracion", "", "", "SI", "NO", "", "L1 ruido en retención en diferencial.")
    agregar("G37-L1-05", CLASE_37, "L1", "Desgaste por fatiga superficial (pitting) en pistas cónicas de rodamientos de diferencial.", "TECNICO", "diagnostico", "desgaste_pitting_rodamientos_diferencial", "", "", "SI", "NO", "", "L1 reporte técnico de pitting en diferencial.")
    agregar("G37-L1-06", CLASE_37, "L1", "Siento un golpeteo y zumbido metálico al doblar cerrado en una esquina.", "COTIDIANO", "curva_cerrada", "zumbido_golpeteo_al_doblar", "", "", "SI", "NO", "", "L1 ruido en planetarios y satélites.")
    agregar("G37-L1-07", CLASE_37, "L1", "El auto zumba fuerte a 80 km/h tanto en línea recta como al doblar.", "COTIDIANO", "velocidad_80kmh", "zumbido_fuerte_80kmh_recta_y_curva", "", "", "SI", "NO", "", "L1 ruido invariable con dirección descarta rueda.")
    agregar("G37-L1-08", CLASE_37, "L1", "Mi carro ase un aullido feo en la carretera como si fuera un avion despegando.", "ERROR_ORTOGRAFICO", "carretera", "aullido_feo_carretera_como_avion", "", "", "SI", "NO", "", "L1 aullido con ortografía informal.")
    agregar("G37-L1-09", CLASE_37, "L1", "Buenas, levantaron el carro en el aire y al girar las llantas la caja suena hueca.", "WHATSAPP", "inspeccion_elevador", "ruedas_girando_caja_suena_hueca", "", "", "SI", "NO", "", "L1 prueba en elevador delata ruido en núcleo de diferencial.")
    agregar("G37-L1-10", CLASE_37, "L1", "Holgura axial y angular fuera de tolerancia en conjunto piñón de ataque y corona.", "TECNICO", "inspeccion", "holgura_axial_pinon_corona", "", "", "SI", "NO", "", "L1 reporte técnico de juego en grupo cónico.")

