    agregar("G37-L2-11", CLASE_37, "L2", "Zumbido en diferencial trasero de vehículo con tracción integral AWD que aparece a partir de 90 km/h; los rodamientos de apoyo de la corona tienen precarga nula.", "COTIDIANO", "autopista_90kmh_awd", "zumbido_diferencial_trasero_90kmh|precarga_nula_corona", "falla_cardan", "", "NO", "NO", "", "L2 pérdida de precarga en diferencial trasero AWD.")
