    agregar("G37-L2-13", CLASE_37, "L2", "Aullido agudo en retención de motor (al soltar el acelerador en bajada con marcha engranada); el rodamiento frontal del piñón de ataque presenta holgura axial.", "TECNICO", "retencion_bajada_marcha", "aullido_en_retencion|holgura_axial_rodamiento_pinon", "falla_caja_engranajes", "", "NO", "NO", "", "L2 aullido específico en desaceleración por juego en piñón.")
